<?php
require __DIR__.'/config.php';
$error='';$msg='';
if(isset($_GET['sair'])){unset($_SESSION['admin_id'],$_SESSION['admin_nome']);header('Location: admin.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'&&!is_admin()){csrf_check();$email=trim($_POST['email']??'');$pass=$_POST['senha']??'';$s=db()->prepare("SELECT * FROM admins WHERE email=?");$s->execute([$email]);$a=$s->fetch();if($a&&password_verify($pass,$a['senha_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_nome']=$a['nome'];header('Location: admin.php');exit;}else{$error='E-mail ou senha inválidos.';}}
if(is_admin()&&isset($_POST['acao'])){csrf_check();try{
if($_POST['acao']==='produto'){ $id=(int)($_POST['id']??0);$nome=trim($_POST['nome']??'');$slug=trim($_POST['slug']??'');$desc=trim($_POST['descricao']??'');$cat=(int)($_POST['categoria_id']??0)?:null;$preco=(float)($_POST['preco']??0);$img=trim($_POST['imagem_url']??'');$ativo=isset($_POST['ativo'])?1:0;$destaque=isset($_POST['destaque'])?1:0;if(!$nome||!$slug||$preco<0)throw new RuntimeException('Nome, slug e preço válido são obrigatórios.');
if($id){$s=db()->prepare("UPDATE produtos SET categoria_id=?,nome=?,slug=?,descricao=?,preco=?,imagem_url=?,ativo=?,destaque=? WHERE id=?");$s->execute([$cat,$nome,$slug,$desc,$preco,$img,$ativo,$destaque,$id]);}else{$s=db()->prepare("INSERT INTO produtos(categoria_id,nome,slug,descricao,preco,imagem_url,ativo,destaque) VALUES(?,?,?,?,?,?,?,?)");$s->execute([$cat,$nome,$slug,$desc,$preco,$img,$ativo,$destaque]);$id=(int)db()->lastInsertId();}
$size=trim($_POST['tamanho']??'Único');$color=trim($_POST['cor']??'Padrão');$stock=max(0,(int)($_POST['estoque']??0));$v=db()->prepare("INSERT INTO variantes_estoque(produto_id,tamanho,cor,estoque) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE estoque=VALUES(estoque)");$v->execute([$id,$size,$color,$stock]);$msg='Produto salvo. Cadastre cada combinação de tamanho/cor como uma variação separada.';
}
if($_POST['acao']==='status_pedido'){$s=db()->prepare("UPDATE pedidos SET status=? WHERE id=?");$s->execute([$_POST['status']??'Recebido',(int)$_POST['pedido_id']]);$msg='Status do pedido atualizado.';}
}catch(Throwable $e){$error=$e instanceof PDOException?'Não foi possível salvar. Verifique se o slug já existe.':$e->getMessage();}}
if(is_admin()){$stats=db()->query("SELECT (SELECT COUNT(*) FROM produtos) produtos,(SELECT COUNT(*) FROM pedidos) pedidos,(SELECT COUNT(*) FROM clientes) clientes,(SELECT COALESCE(SUM(total),0) FROM pedidos WHERE status<>'Cancelado') vendas")->fetch();$products=db()->query("SELECT p.*,c.nome categoria FROM produtos p LEFT JOIN categorias c ON c.id=p.categoria_id ORDER BY p.criado_em DESC")->fetchAll();$cats=db()->query("SELECT * FROM categorias ORDER BY nome")->fetchAll();$orders=db()->query("SELECT * FROM pedidos ORDER BY criado_em DESC LIMIT 50")->fetchAll();}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administração | Loja BY</title><link rel="stylesheet" href="style.css"></head><body><header class="top"><a class="brand" href="index.php"><span class="logo">BY</span><span>LOJA BY<small>PAINEL ADMINISTRATIVO</small></span></a><nav class="nav"><a href="index.php">Ver loja</a><?php if(is_admin()):?><a href="?sair=1">Sair</a><?php endif?></nav></header><main class="wrap"><?php if(!is_admin()):?><div class="card" style="max-width:480px;margin:55px auto"><h1>Entrar no painel BY</h1><p class="muted">Área restrita ao proprietário.</p><?php if($error):?><div class="notice error"><?=h($error)?></div><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><div class="field"><label>E-mail administrativo</label><input type="email" name="email" required></div><div class="field" style="margin:15px 0"><label>Senha</label><input type="password" name="senha" required></div><button class="btn">Entrar</button></form><p class="muted">Crie o primeiro administrador usando o comando seguro descrito no README. Não existe senha padrão.</p></div><?php else:?>
<h1>Painel administrativo</h1><p>Olá, <?=h($_SESSION['admin_nome'])?>. Aqui você gerencia a Loja BY.</p><?php if($msg):?><div class="notice success"><?=h($msg)?></div><?php endif?><?php if($error):?><div class="notice error"><?=h($error)?></div><?php endif?>
<div class="stat-grid"><div class="stat">Produtos<strong><?=$stats['produtos']?></strong></div><div class="stat">Pedidos<strong><?=$stats['pedidos']?></strong></div><div class="stat">Clientes<strong><?=$stats['clientes']?></strong></div><div class="stat">Vendas registradas<strong><?=money($stats['vendas'])?></strong></div></div>
<div class="card"><h2>Cadastrar produto</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="produto"><div class="form-grid"><div class="field"><label>Nome do produto</label><input name="nome" required></div><div class="field"><label>Slug único (ex.: camiseta-by)</label><input name="slug" required pattern="[a-z0-9-]+"></div><div class="field"><label>Categoria</label><select name="categoria_id"><option value="">Sem categoria</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=h($c['nome'])?></option><?php endforeach?></select></div><div class="field"><label>Preço (R$)</label><input type="number" step=".01" min="0" name="preco" required></div><div class="field wide"><label>Descrição</label><textarea name="descricao"></textarea></div><div class="field wide"><label>URL da imagem</label><input type="url" name="imagem_url" placeholder="https://..."></div><div class="field"><label>Tamanho da variação inicial</label><input name="tamanho" value="M" required></div><div class="field"><label>Cor da variação inicial</label><input name="cor" value="Preto" required></div><div class="field"><label>Estoque inicial</label><input type="number" min="0" name="estoque" value="0" required></div><div class="field"><label><input type="checkbox" name="ativo" checked> Produto ativo</label><label><input type="checkbox" name="destaque"> Destacar na página inicial</label></div></div><p><button class="btn">Salvar produto</button></p></form></div>
<div class="card"><h2>Produtos cadastrados</h2><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Categoria</th><th>Preço</th><th>Ativo</th><th>Estoque</th></tr></thead><tbody><?php foreach($products as $p):$st=db()->prepare("SELECT COALESCE(SUM(estoque),0) FROM variantes_estoque WHERE produto_id=?");$st->execute([$p['id']]);?><tr><td><?=h($p['nome'])?><br><small><?=h($p['slug'])?></small></td><td><?=h($p['categoria']??'—')?></td><td><?=money($p['preco'])?></td><td><?=$p['ativo']?'Sim':'Não'?></td><td><?=$st->fetchColumn()?></td></tr><?php endforeach?></tbody></table></div></div>
<div class="card"><h2>Pedidos recentes</h2><div class="table-wrap"><table><thead><tr><th>Código</th><th>Cliente</th><th>Total</th><th>Pagamento</th><th>Status</th><th>Atualizar</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=h($o['codigo'])?></td><td><?=h($o['cliente_nome'])?><br><small><?=h($o['email'])?></small></td><td><?=money($o['total'])?></td><td><?=h($o['forma_pagamento'])?></td><td><?=h($o['status'])?></td><td><form method="post" style="display:flex;gap:5px"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="acao" value="status_pedido"><input type="hidden" name="pedido_id" value="<?=$o['id']?>"><select name="status"><option>Recebido</option><option>Pagamento confirmado</option><option>Em preparação</option><option>Enviado</option><option>Entregue</option><option>Cancelado</option></select><button class="btn">Salvar</button></form></td></tr><?php endforeach?></tbody></table></div></div>
<?php endif?></main><footer class="footer">LOJA BY • Administração segura</footer></body></html>
